INSERT OR IGNORE INTO materials (ark,created_by,type,title_ar,title_orig,description,summary,language,year,date_confidence,archive_ref,source_url,rights,full_text,transcription_status,translation_status,publish_status,created_via,source_attribution,rights_status) VALUES ('ARC-TD-ART-000009',1,'article','هندسة القطيعة — وثيقة التوجيه المنهجي والتحريري','هندسة القطيعة — وثيقة التوجيه المنهجي والتحريري','دستور تحريري ومنهجي للبحث في تاريخ تشاد، يحدد معايير التوثيق والنقد وبناء الفصول.','وثيقة عمل تضع منهجًا لبناء كتاب نقدي في الاستعمار والتغريب والهوية التشادية، وتحدد دور الباحث في جمع الوثائق وفحصها وتركيب الحجة.','ar',NULL,'unknown',NULL,NULL,'unknown','', 'corrected','none','published','drive_import','نص موثق مستخرج من وثيقة TCHAD الأصلية؛ يُعرض للقراءة داخل المنصة ولا يُتاح كملف Word أو نص للتنزيل.','unknown');
